def _bfs(n, start, target, block):
    # Move a single hand from start to target on the ring of n parts,
    # never stepping onto `block` (the other hand, which stays fixed).
    if start == target:
        return 0
    dist = {start: 0}
    queue = [start]
    idx = 0
    while idx < len(queue):
        x = queue[idx]
        idx += 1
        for y in (x % n + 1, (x - 2) % n + 1):
            if y == block or y in dist:
                continue
            dist[y] = dist[x] + 1
            if y == target:
                return dist[y]
            queue.append(y)
    return None


